// Generated by tack build. Do not edit. Codex runs this when a session
// starts. It appends one load marker line to TACK_RECORDER and prints
// nothing, so Codex adds no context to the session.

import { appendFileSync } from "node:fs";

const BUDGET_MS = __TACK_BUDGET_MS__;
const MARKER = JSON.stringify({ call: "tack-loaded" }) + "\n";

// Drain Codex's input first so its write never meets a closed pipe.
function main(stdin, env, exit) {
  let done = false;
  const timer = setTimeout(finish, BUDGET_MS);

  function finish() {
    if (done) return;

    done = true;
    clearTimeout(timer);

    let code = 0;

    try {
      if (env.TACK_RECORDER) appendFileSync(env.TACK_RECORDER, MARKER);
    } catch {
      code = 1;
    }

    exit(code);
  }

  stdin.on("end", finish);
  stdin.on("error", finish);
  stdin.resume();
}

main(process.stdin, process.env, (code) => process.exit(code));
